export function getAgravoByCode(codigo: string): SinanAgravo | undefined {
  return SINAN_AGRAVOS.find(a => a.codigo === codigo);
}

export function getAgravosByCat(categoria: string): SinanAgravo[] {
  return SINAN_AGRAVOS.filter(a => a.categoria === categoria);
}

export function getAllAgravos(): SinanAgravo[] {
  return SINAN_AGRAVOS;
}

export function getAgravosImediatos(): SinanAgravo[] {
  return SINAN_AGRAVOS.filter(a => a.prazoNotificacao === "imediata");
}

export function buildSinanTemplate(agravo: SinanAgravo): TemplateDefinition {
  return {
    pageSize: { width: 2100, height: 2970 },
    fields: agravo.campos,
  };
}
